import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { a: 10, b: 40, c: 10.5, d: 100, e: 101, f: 100.01, g: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const base = `http://localhost:${server.address().port}`
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(fetched.total, order.total)
    return order.total
  } finally {
    server.close()
  }
}

// These pin CURRENT behavior, including the questionable parts (see notes).
test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]), 60)
})

test('no discount at exactly 100', async () => {
  assert.equal(await totalFor([{ sku: 'd', qty: 1 }]), 100)
})

test('10% discount applies strictly above 100', async () => {
  assert.equal(await totalFor([{ sku: 'b', qty: 3 }]), 108)
})

test('just over the threshold: 101 -> 90 (discounted total floored)', async () => {
  assert.equal(await totalFor([{ sku: 'e', qty: 1 }]), 90)
})

test('crossing the threshold lowers the total (100 -> 100, 101 -> 90)', async () => {
  assert.ok((await totalFor([{ sku: 'e', qty: 1 }])) < (await totalFor([{ sku: 'd', qty: 1 }])))
})

test('large order: 1000 * 5 = 5000 -> 4500', async () => {
  assert.equal(await totalFor([{ sku: 'g', qty: 5 }]), 4500)
})

test('fractional euros are truncated, not rounded: 31.5 -> 31', async () => {
  assert.equal(await totalFor([{ sku: 'c', qty: 3 }]), 31)
})

test('100.01 -> 90 (90.009 floored)', async () => {
  assert.equal(await totalFor([{ sku: 'f', qty: 1 }]), 90)
})
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"

